Two Dimensional Array with User inputFollow the steps mentioned below to create a two-dimensional array with user input:First, import the Scanner class from the java.util package at the top of the program.Then create a Scanner class object. Then give a prompt to user to enter the size of row and column.Then create a nested loop to take input from user to add element in the multi-dimensional array.Then print the multi-dimensional array and close the scanner object.Example: Java program to demonstrate how to create Two Dimensional Array with User input.
            Java

    import java.util.Scanner;

public class Geeks 
{
    public static void main(String[] args){

        Scanner sc = new Scanner(System.in);

      	// Taking Number of Rows and Columns from User
        System.out.print("Enter number of rows: ");
      	int row = sc.nextInt();

        System.out.print("Enter number of columns: ");
        int col = sc.nextInt();

        int[][] arr= new int[row][col];

        System.out.println("Enter elements of array: ");

        // Taking input from user for each element of array using nested for loop
        for (int i = 0; i < row; i++) {
            for (int j = 0; j < col; j++) {
                arr[i][j]= sc.nextInt();
            }
        }


         System.out.println("Elements of array are: ");
      	// Printing Elements of Arrays
        for (int i = 0; i < row; i++) {
            for (int j = 0; j < col; j++) {
                System.out.print(arr[i][j]+ " ");
            }

            System.out.println();
        }
        sc.close();
    }
}

