Inserting a Multi-Dimensional Array During RuntimeNow we can insert a multidimensional array at runtime here we are going to use the Scanner class and then we take the element of the multidimensional array from the user and then we print the count of the even and odd element which user give as an input.Example: Taking a input from user of multidimensional array (Runtime) and print the count of even and odd number given by user.
            Java

    import java.io.*;
import java.util.Scanner;

class Geeks {
    public static void main(String[] args)
    {
        Scanner s = new Scanner(System.in);

        // Number of rows
        int n = s.nextInt();

        // Initialize a 2D array
        int[][] arr = new int[n][];
        int t = 0;

        // Input for each row
        for (int i = 0; i < n; i++) {
            int m = s.nextInt();
            // Assuming all rows have the same column count
            t = m;
            arr[i] = new int[m];

            for (int j = 0; j < m; j++) {
                arr[i][j] = s.nextInt();
            }
        }

        int odd = 0, even = 0;

        System.out.println("Rows " + n + " with " + t
                           + " Columns");
        System.out.println("Elements of Array:");

        // Print the entire array and count even/odd numbers
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < arr[i].length; j++) {
                System.out.print(arr[i][j] + " ");

                // Count even and odd numbers
                if (arr[i][j] % 2 == 0) {
                    even++;
                }
                else {
                    odd++;
                }
            }
            System.out.println();
        }

        // Print the aggregated results
        System.out.println("Even: " + even
                           + ", Odd: " + odd);

        s.close();
    }
}

